import psycopg2


# Reference: https://github.com/ubiquiti/unifi-protect-fw-sqa/blob/develop/ubnt-sqa-automation/src/postgres/psql_module.py
class PsqlModule():
    def __init__(self,
                 user='unifi-protect',
                 pwd=None,
                 db='unifi-protect',
                 host='/var/run/postgresql',
                 port='5433'):
        self.conn = psycopg2.connect(database=db,
                                     user=user,
                                     password=pwd,
                                     host=host,
                                     port=port)
        self.cur = self.conn.cursor()

    def ReadData(self, table_name: str, select_key=['*'], data_filter=''):
        keys = ', '.join(['"{}"'.format(_key) for _key in select_key
                          ]) if select_key != ['*'] else '*'

        cmd = 'SELECT {} from "{}" '.format(keys, table_name)
        cmd += data_filter

        self.cur.execute(cmd)

        return PsqlData(self.cur)

    def ReadDataWithRawCommand(self, cmd):
        self.cur.execute(cmd)

        return PsqlData(self.cur)


class PsqlData():
    def __init__(self, cur):
        self.cur = cur
        self.rows = []
        self.row_num = 0
        self.row_cur = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.row_cur < self.row_num:
            data = self.rows[self.row_cur]
            self.row_cur += 1
            return data
        self.__FetchNewData()
        if not self.rows: raise StopIteration
        return self.__next__()

    def __FetchNewData(self):
        self.rows = self.cur.fetchmany(100)
        self.row_num = len(self.rows)
        self.row_cur = 0
